// Parâmetros globais do relatório (ajustar metas conforme governança)
// Data-base D-1 calculada no fuso America/Sao_Paulo.
const iso = new Intl.DateTimeFormat('sv-SE', { timeZone: 'America/Sao_Paulo' })
  .format(new Date(Date.now() - 24 * 60 * 60 * 1000));   // yyyy-MM-dd
const [ano, mes, dia] = iso.split('-').map(Number);
const MESES = ['jan', 'fev', 'mar', 'abr', 'mai', 'jun', 'jul', 'ago', 'set', 'out', 'nov', 'dez'];
const siteFiltro = 'HUB RIO';                       // escopo do relatório (hub de e-commerce)

// --- Consultas DAX do painel Power BI "Pendência E-commerce" (executeQueries) ---
// Datas explícitas (não usa TODAY(): o serviço do Power BI roda em UTC). Mês vigente = mês de D-1, do dia 1 até D-1.
// Ruptura % = peças alteradas (todos os motivos) ÷ peças em picking; sem DEFINE MEASURE (usa só colunas do modelo).
const dD1 = `DATE(${ano},${mes},${dia})`;
const dIni = `DATE(${ano},${mes},1)`;
const fSite = `TREATAS({"${siteFiltro}"}, DIM_SITE[SITE])`;
const cDia = `DIM_CALENDARIO[Date] = ${dD1}`;
const cMesA = `DIM_CALENDARIO[Date] >= ${dIni}`;
const cMesB = `DIM_CALENDARIO[Date] <= ${dD1}`;
const rup = `SUM('Base Ruptura'[QTDE_ALTERADA])`;
const pick = `SUM('Base Picking'[QTDE_PECAS])`;
const pbiQueries = [
  // 0: total do dia (D-1)
  `EVALUATE ROW("ruptura", CALCULATE(${rup}, ${fSite}, ${cDia}), "picking", CALCULATE(${pick}, ${fSite}, ${cDia}))`,
  // 1: total do mês (1º dia até D-1)
  `EVALUATE ROW("ruptura", CALCULATE(${rup}, ${fSite}, ${cMesA}, ${cMesB}), "picking", CALCULATE(${pick}, ${fSite}, ${cMesA}, ${cMesB}))`,
  // 2: por marca, dia
  `EVALUATE SUMMARIZECOLUMNS(DIM_MARCA[MARCA], ${fSite}, FILTER(ALL(DIM_CALENDARIO[Date]), ${cDia}), "ruptura", ${rup}, "picking", ${pick})`,
  // 3: por marca, mês
  `EVALUATE SUMMARIZECOLUMNS(DIM_MARCA[MARCA], ${fSite}, FILTER(ALL(DIM_CALENDARIO[Date]), ${cMesA} && ${cMesB}), "ruptura", ${rup}, "picking", ${pick})`
];

return [{
  json: {
    grupo: 'AZZAS 2154',
    dataBase: iso,
    dataBaseBR: iso.split('-').reverse().join('/'),
    mesLabel: `${MESES[mes - 1]}/${ano}`,   // mês vigente (mês de D-1)
    slaMetaPct: 95,                      // Meta SLA (%) - % de pedidos expedidos dentro da meta de lead time
    leadTimeMetaH: 24,                   // Meta Lead Time (h): venda -> expedição
    rupturaMetaPct: 1,                   // Meta Ruptura (%)
    siteFiltro,
    pbiQueries,
    // Fusão opcional de marcas do DW (chave normalizada -> chave de destino). Vazio = todas as marcas abertas.
    // Ex.: { 'FARM ETC': 'FARM', 'FARM BEACHWEAR': 'FARM' }
    aliasMarcas: {},
    // Nome de exibição por chave normalizada (maiúsculas, sem acento). Demais: Title Case automático.
    nomesMarcas: { 'BYNV': 'NV', 'MARIA FILO': 'Maria Filó', 'FABULA': 'Fábula' }
  }
}];

// Consolida SQL E-commerce + Power BI (ruptura) no contrato único de dados do relatório.
// Todas as marcas retornadas pelo SQL são abertas individualmente (sem "Demais marcas").
// Ruptura vem do Power BI; se o Power BI falhar ou ainda não tiver o dia, o indicador fica nulo (o HTML exibe "—").
const safe = (name) => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
const cfg = $('Parâmetros').first().json;
const n = (v) => Number(v) || 0;
const norm = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().trim();
const titleCase = (s) => s.toLowerCase().replace(/(^|\s)\S/g, (c) => c.toUpperCase());
const alias = cfg.aliasMarcas || {};
const nomes = cfg.nomesMarcas || {};
const pct = (a, b) => (b > 0 ? (a / b) * 100 : null);

// ---------- SQL: uma linha por MARCA + linha TOTAL (pedidos únicos) ----------
const todasLinhas = safe('SQL - E-commerce');
const linhaTotal = todasLinhas.find(r => Number(r.eh_total) === 1);
const linhasSql = todasLinhas.filter(r => Number(r.eh_total) !== 1);

const zero = () => ({ ped_i: 0, pc_i: 0, rs_i: 0, ped_a: 0, pc_a: 0, rs_a: 0, ped_p: 0, pc_p: 0, rs_p: 0,
  b7_ped: 0, b7_pc: 0, b7_rs: 0, sla_ok: 0, sla_base: 0, lt_soma: 0, lt_qtd: 0, ltm_soma: 0, ltm_qtd: 0 });
const acc = {};

linhasSql.forEach(r => {
  let k = norm(r.MARCA ?? r.marca) || 'SEM MARCA';
  k = alias[k] ? norm(alias[k]) : k;
  const b = (acc[k] = acc[k] || zero());
  b.ped_i += n(r.ped_integrado); b.pc_i += n(r.pc_integrado); b.rs_i += n(r.rs_integrado);
  b.ped_a += n(r.ped_atendido);  b.pc_a += n(r.pc_atendido);  b.rs_a += n(r.rs_atendido);
  b.ped_p += n(r.ped_pendente);  b.pc_p += n(r.pc_pendente);  b.rs_p += n(r.rs_pendente);
  b.b7_ped += n(r.ped_backlog_7d); b.b7_pc += n(r.pc_backlog_7d); b.b7_rs += n(r.rs_backlog_7d);
  b.sla_ok += n(r.sla_cumprido); b.sla_base += n(r.sla_base);
  b.lt_soma += n(r.soma_lead_time_h);     b.lt_qtd += n(r.qtd_expedidos);
  b.ltm_soma += n(r.soma_lead_time_h_mes); b.ltm_qtd += n(r.qtd_expedidos_mes);
});

// ---------- Power BI: ruptura (resultado de 4 consultas na ordem de cfg.pbiQueries) ----------
let rp = null;
try { rp = $('Ruptura_Ecommerce').first().json; } catch (e) { rp = null; }
const pbiRows = (i) => ((rp && rp.results && rp.results[i] && rp.results[i].tables && rp.results[i].tables[0] && rp.results[i].tables[0].rows) || [])
  .map(r => { const o = {}; Object.keys(r).forEach(k => { o[k.replace(/^.*\[|\]$/g, '')] = r[k]; }); return o; });
const rupTotal = (i) => { const r = pbiRows(i)[0]; return r ? { r: n(r.ruptura), p: n(r.picking) } : { r: 0, p: 0 }; };
const rupDia = rupTotal(0), rupMes = rupTotal(1);

// Marcas do Power BI -> mesma chave do SQL (Animale Jeans entra em Animale; NV = BYNV). Marca em branco só entra no total.
const keyPbi = (s) => {
  let k = norm(s);
  if (!k) return null;
  if (k.includes('FOXTON')) k = 'FOXTON'; else if (k.includes('FABULA')) k = 'FABULA'; else if (k.includes('ANIMALE')) k = 'ANIMALE';
  if (k === 'NV' && !acc['NV'] && acc['BYNV']) k = 'BYNV';
  return alias[k] ? norm(alias[k]) : k;
};
const rupMarca = {};
[[2, 'dia'], [3, 'mes']].forEach(([i, per]) => pbiRows(i).forEach(r => {
  const k = keyPbi(r.MARCA); if (!k) return;
  const o = (rupMarca[k] = rupMarca[k] || { dia: { r: 0, p: 0 }, mes: { r: 0, p: 0 } });
  o[per].r += n(r.ruptura); o[per].p += n(r.picking);
}));

// ---------- Tabela por marca (não é afetada pelo filtro de marca) ----------
const marcas = Object.entries(acc)
  .filter(([, v]) => v.ped_i + v.ped_a + v.ped_p > 0)
  .map(([k, v]) => ({ chave: k, nome: nomes[k] || titleCase(k), ...v }))
  .sort((a, b) => b.ped_i - a.ped_i || a.nome.localeCompare(b.nome, 'pt-BR'));

let total = zero();
if (linhaTotal) {
  // Pedidos únicos no grupo (mesma regra do Power BI); um pedido com mais de uma marca conta em cada marca.
  total = { ...total,
    ped_i: n(linhaTotal.ped_integrado), pc_i: n(linhaTotal.pc_integrado), rs_i: n(linhaTotal.rs_integrado),
    ped_a: n(linhaTotal.ped_atendido),  pc_a: n(linhaTotal.pc_atendido),  rs_a: n(linhaTotal.rs_atendido),
    ped_p: n(linhaTotal.ped_pendente),  pc_p: n(linhaTotal.pc_pendente),  rs_p: n(linhaTotal.rs_pendente),
    b7_ped: n(linhaTotal.ped_backlog_7d), b7_pc: n(linhaTotal.pc_backlog_7d), b7_rs: n(linhaTotal.rs_backlog_7d),
    sla_ok: n(linhaTotal.sla_cumprido), sla_base: n(linhaTotal.sla_base) };
} else {
  marcas.forEach(m => ['ped_i','pc_i','rs_i','ped_a','pc_a','rs_a','ped_p','pc_p','rs_p','b7_ped','b7_pc','b7_rs','sla_ok','sla_base'].forEach(k => total[k] += m[k]));
}
Object.values(acc).forEach(v => { total.lt_soma += v.lt_soma; total.lt_qtd += v.lt_qtd; total.ltm_soma += v.ltm_soma; total.ltm_qtd += v.ltm_qtd; });

// ---------- Indicadores (filtráveis por marca) ----------
// SLA: pedidos vendidos em D-1 expedidos dentro da meta ÷ (cumpridos + descumpridos). Pendentes ainda dentro do prazo ficam fora da base.
const indicadores = (v, rd, rm) => ({
  ped_i: v.ped_i, pc_i: v.pc_i, rs_i: v.rs_i, ped_a: v.ped_a, pc_a: v.pc_a, rs_a: v.rs_a, ped_p: v.ped_p, pc_p: v.pc_p, rs_p: v.rs_p,
  slaPct: pct(v.sla_ok, v.sla_base),
  leadTimeH: v.lt_qtd > 0 ? v.lt_soma / v.lt_qtd : null,           // média venda -> expedição (expedidos em D-1)
  leadTimeMesH: v.ltm_qtd > 0 ? v.ltm_soma / v.ltm_qtd : null,     // idem, expedidos de 1º do mês até D-1
  backlogAcimaSlaPed: v.b7_ped,                                    // backlog D-7: pendentes agora, vendidos de D-7 a D-1
  rupturaDiaPct: rd && rd.p > 0 ? pct(rd.r, rd.p) : null,          // peças alteradas ÷ picking, D-1
  rupturaMesPct: rm && rm.p > 0 ? pct(rm.r, rm.p) : null           // idem, mês vigente até D-1
});
const filtros = [{ id: 'todas', nome: 'Todas', ind: indicadores(total, rupDia, rupMes) }]
  .concat(marcas.map(m => ({ id: m.chave, nome: m.nome, ind: indicadores(m, (rupMarca[m.chave] || {}).dia, (rupMarca[m.chave] || {}).mes) })));

const kpis = filtros[0].ind;
return [{ json: { cfg, marcas, total, kpis, filtros, pbiOk: !!(rp && rp.results), geradoEm: new Date().toISOString() } }];

// Renderiza o template "DAILY LOGISTICS | ONE PAGE" a partir do contrato de dados.
// Os filtros de visão (Pedidos / Peças / Valor) e de marca são 100% CSS (radio + :checked), sem JavaScript,
// para funcionar mesmo quando o n8n serve o HTML em sandbox.
// O filtro de marca altera apenas os indicadores (blocos de resumo e de nível de serviço); a tabela não é filtrada.
const { cfg, marcas, total, filtros } = $input.first().json;
const hhmm = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: 'America/Sao_Paulo' });

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const isN = (v) => v === null || v === undefined || isNaN(v);
const num = (v) => isN(v) ? '—' : Number(v).toLocaleString('pt-BR', { maximumFractionDigits: 0 });
const dec = (v, c = 1) => isN(v) ? '—' : Number(v).toLocaleString('pt-BR', { minimumFractionDigits: c, maximumFractionDigits: c });
const mil = (v) => isN(v) ? '—' : (v >= 1000 ? dec(v / 1000, 1) + ' mil' : num(v));
const brl = (v) => isN(v) ? '—' : 'R$ ' + (v >= 1e6 ? dec(v / 1e6, 2) + ' mi' : num(v));
const sub = (p, c, r) => `${num(p)} pedidos • ${num(c)} peças • ${brl(r)}`;
const withUnit = (v, fmt, unit) => isN(v) ? '—' : fmt(v) + unit;
// célula com as três visões; o CSS exibe somente a selecionada
const cell = (p, c, r) => `<span class="vp">${num(p)}</span><span class="vc">${num(c)}</span><span class="vr">${brl(r)}</span>`;
const row = (nome, v, cls = '') => `<tr${cls}><td>${esc(nome)}</td><td class="n">${cell(v.ped_i, v.pc_i, v.rs_i)}</td><td class="n">${cell(v.ped_a, v.pc_a, v.rs_a)}</td><td class="n">${cell(v.ped_p, v.pc_p, v.rs_p)}</td></tr>`;

// regras de CSS geradas por marca (índice 0 = Todas)
const cssMarca = filtros.map((f, i) =>
  `#m-${i}:checked ~ .mk-${i}{display:grid}` +
  `#m-${i}:checked ~ .brandbar label[for=m-${i}]{background:#1a1a1a;color:#fff}` +
  `#m-${i}:focus-visible ~ .brandbar label[for=m-${i}]{outline:2px solid #2563eb}`).join('\n');

const css = `
body{font-family:Segoe UI,Arial,sans-serif;color:#1a1a1a;margin:0;background:#fff}
.page{max-width:720px;margin:0 auto;padding:24px;position:relative}
h1{font-size:16px;margin:0}.meta{font-size:11px;color:#666;margin:2px 0 12px}
.brandbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:0 0 4px;font-size:11px;color:#555}
.chips{display:inline-flex;gap:4px;flex-wrap:wrap}
.chips label{padding:3px 10px;cursor:pointer;background:#fff;color:#333;border:1px solid #bbb;border-radius:12px;user-select:none}
.bnote{font-size:10px;color:#777;margin:0 0 16px}
.kpis{display:grid;grid-template-columns:1fr 1fr;gap:16px 40px;margin-bottom:24px}
.kpi .l{font-size:12px;color:#555}.kpi .v{font-size:24px;font-weight:700;margin:2px 0}.kpi .s{font-size:10px;color:#666}
h2{font-size:13px;margin:22px 0 4px;border-bottom:1px solid #ddd;padding-bottom:4px}
.sec1head{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:22px 0 4px;border-bottom:1px solid #ddd;padding-bottom:4px}
.sec1head h2{margin:0;padding:0;border:0}
.seg{display:flex;align-items:center;gap:6px;font-size:11px;color:#555}
.seg .opts{display:inline-flex;border:1px solid #bbb;border-radius:4px;overflow:hidden}
.seg label{padding:3px 10px;cursor:pointer;background:#fff;color:#333;user-select:none}
.seg label+label{border-left:1px solid #bbb}
.rad{position:absolute;opacity:0;width:0;height:0;pointer-events:none}
.vc,.vr{display:none}
.mk{display:none}
${cssMarca}
#v-pd:checked ~ .sec1 label[for=v-pd],#v-pc:checked ~ .sec1 label[for=v-pc],#v-rs:checked ~ .sec1 label[for=v-rs]{background:#1a1a1a;color:#fff}
#v-pc:checked ~ .sec1 .vp,#v-rs:checked ~ .sec1 .vp{display:none}
#v-pc:checked ~ .sec1 .vc{display:inline}
#v-rs:checked ~ .sec1 .vr{display:inline}
#v-pd:focus-visible ~ .sec1 label[for=v-pd],#v-pc:focus-visible ~ .sec1 label[for=v-pc],#v-rs:focus-visible ~ .sec1 label[for=v-rs]{outline:2px solid #2563eb}
table{width:100%;border-collapse:collapse;font-size:11px}
th{text-align:left;padding:6px 4px;border-bottom:2px solid #1a1a1a}
th.n,td.n{text-align:right}
td{padding:7px 4px;border-bottom:1px solid #e5e5e5}
tr.total td{font-weight:700;border-top:2px solid #1a1a1a}
.cards{display:none;grid-template-columns:1fr 1fr;gap:10px}
.card{border:1px solid #ccc;border-radius:4px;padding:10px 12px}
.note{font-size:10px;color:#777;margin-top:6px}
.card .l{font-size:11px;color:#555}.card .v{font-size:20px;font-weight:700;margin:2px 0}.card .s{font-size:10px;color:#777}
@media (max-width:520px){.kpis,.cards{grid-template-columns:1fr}}
`;

const radiosMarca = filtros.map((f, i) => `<input class="rad" type="radio" name="marca" id="m-${i}"${i === 0 ? ' checked' : ''} aria-label="Marca: ${esc(f.nome)}">`).join('\n');
const chips = filtros.map((f, i) => `<label for="m-${i}">${esc(f.nome)}</label>`).join('');

const blocoKpis = (f, i) => { const v = f.ind; return `<div class="kpis mk mk-${i}">
  <div class="kpi"><div class="l">Demanda integrada</div><div class="v">${mil(v.ped_i)}</div><div class="s">${sub(v.ped_i, v.pc_i, v.rs_i)}</div></div>
  <div class="kpi"><div class="l">Volume atendido</div><div class="v">${mil(v.ped_a)}</div><div class="s">${sub(v.ped_a, v.pc_a, v.rs_a)}</div></div>
  <div class="kpi"><div class="l">Backlog pendente</div><div class="v">${mil(v.ped_p)}</div><div class="s">${sub(v.ped_p, v.pc_p, v.rs_p)}</div></div>
  <div class="kpi"><div class="l">Cumprimento do SLA</div><div class="v">${withUnit(v.slaPct, dec, '%')}</div><div class="s">Meta: ${cfg.slaMetaPct}% • pedidos de D-1 expedidos em até ${cfg.leadTimeMetaH} h</div></div>
</div>`; };

const indis = (v) => isN(v) ? ' • indisponível' : '';
const blocoCards = (f, i) => { const v = f.ind; return `<div class="cards mk mk-${i}">
  <div class="card"><div class="l">Lead Time médio (D-1)</div><div class="v">${withUnit(v.leadTimeH, (x) => dec(x, 1), ' h')}</div><div class="s">Meta: ${cfg.leadTimeMetaH} h • expedidos em D-1</div></div>
  <div class="card"><div class="l">Lead Time médio (mês)</div><div class="v">${withUnit(v.leadTimeMesH, (x) => dec(x, 1), ' h')}</div><div class="s">Meta: ${cfg.leadTimeMetaH} h • ${esc(cfg.mesLabel)} até D-1</div></div>
  <div class="card"><div class="l">Ruptura (D-1)</div><div class="v">${withUnit(v.rupturaDiaPct, (x) => dec(x, 2), '%')}</div><div class="s">Meta: ${dec(cfg.rupturaMetaPct, 2)}% • peças alteradas ÷ picking${indis(v.rupturaDiaPct)}</div></div>
  <div class="card"><div class="l">Ruptura mensal</div><div class="v">${withUnit(v.rupturaMesPct, (x) => dec(x, 2), '%')}</div><div class="s">Meta: ${dec(cfg.rupturaMetaPct, 2)}% • ${esc(cfg.mesLabel)} até D-1${indis(v.rupturaMesPct)}</div></div>
  <div class="card"><div class="l">Backlog acima do SLA</div><div class="v">${withUnit(v.backlogAcimaSlaPed, num, ' pedidos')}</div><div class="s">Pendentes agora, vendidos nos últimos 7 dias</div></div>
</div>`; };

const linhas = marcas.map(m => row(m.nome, m)).join('');
const linhaTotal = row('TOTAL GRUPO', total, ' class="total"');

const html = `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daily Logistics | One Page</title><style>${css}</style></head><body><div class="page">
<input class="rad" type="radio" name="visao" id="v-pd" checked aria-label="Visão por pedidos">
<input class="rad" type="radio" name="visao" id="v-pc" aria-label="Visão por peças">
<input class="rad" type="radio" name="visao" id="v-rs" aria-label="Visão por valor">
${radiosMarca}
<h1>DAILY LOGISTICS | ONE PAGE</h1>
<div class="meta">${esc(cfg.grupo)} • E-commerce ${esc(cfg.siteFiltro)} • Data-base: D-1 (${esc(cfg.dataBaseBR)}) • Atualizado às ${hhmm}</div>
<div class="brandbar"><span>Marca:</span><span class="chips">${chips}</span></div>
<div class="bnote">O filtro de marca altera apenas os indicadores; a tabela mostra todas as marcas.</div>

${filtros.map(blocoKpis).join('\n')}

<div class="sec1">
<div class="sec1head"><h2>1. DEMANDA E ATENDIMENTO POR MARCA</h2>
  <div class="seg"><span>Visão:</span><span class="opts"><label for="v-pd">Pedidos</label><label for="v-pc">Peças</label><label for="v-rs">Valor</label></span></div>
</div>
<table><thead><tr><th>Marca</th><th class="n">Integrado</th><th class="n">Atendido</th><th class="n">Pendente</th></tr></thead><tbody>
${linhas}
${linhaTotal}
</tbody></table>
<div class="note vp">Pedidos: contagem única (filial + pedido), exceto cancelados. O total pode ser menor que a soma das marcas, pois um pedido com mais de uma marca aparece em cada marca.</div>
</div>

<h2>2. NÍVEL DE SERVIÇO E RISCOS</h2>
${filtros.map(blocoCards).join('\n')}
</div></body></html>`;

return [{ json: { html, assunto: `Daily Logistics | ${cfg.grupo} | ${cfg.dataBaseBR}`, dataBase: cfg.dataBase } }];

// Guarda o último HTML gerado (static data do workflow) para o webhook servir sem reconsultar o banco.
// Atenção: static data só persiste em execuções de produção (workflow ativo); execuções manuais de teste não gravam.
const sd = $getWorkflowStaticData('global');
const item = $input.first().json;
sd.html = item.html;
sd.dataBase = item.dataBase;
sd.geradoEm = new Date().toISOString();
return $input.all();

// Verifica se há relatório em cache recente (<= 70 min). Se não houver, o fluxo gera na hora (consulta o SQL).
const sd = $getWorkflowStaticData('global');
const idadeMin = (sd.html && sd.geradoEm) ? Math.round((Date.now() - new Date(sd.geradoEm).getTime()) / 60000) : null;
const cacheOk = idadeMin !== null && idadeMin <= 70;
return [{ json: { cacheOk, idadeMin, html: cacheOk ? sd.html : null } }];
